file.content:
[
  {
    "id": "c001",
    "name": "Preamble—Parties and defined terms",
    "text": "This GUARANTEE AGREEMENT, dated as of December 29, 2010, made by and between ESSAR GLOBAL LIMITED, a company incorporated in the Cayman Islands (“EGL” or the “Guarantor” as the case may be), and ESSAR STEEL MINNESOTA LLC, a Minnesota limited liability company (the “Borrower”), in favor of ICICI BANK LIMITED, SINGAPORE BRANCH, as Facility Agent (including any successor Facility Agent, the “Facility Agent”) on behalf of ICICI BANK LIMITED, NEW YORK BRANCH, as a Lender (the “Initial Lender”) which is a party, and the Subsequent Project Lenders (together with the Initial Lender, the “Lenders”) from time to time which shall become parties, to the Senior Secured Credit Agreement, dated as of December 29, 2010 (as restated, amended, supplemented or otherwise modified from time to time, the “Credit Agreement”), among the Borrower, the Lenders party thereto, the Issuing Bank, the Agents named therein and ICICI Bank Limited, New York Branch, as Mandated Lead Arranger."
  },
  {
    "id": "c002",
    "name": "Recital—Credit Agreement obligations",
    "text": "WHEREAS, pursuant to the Credit Agreement, the Lenders have agreed to severally make extensions of credit to the Borrower upon the terms and subject to the conditions set forth therein;"
  },
  {
    "id": "c003",
    "name": "Recital—Condition precedent",
    "text": "WHEREAS, it is a condition precedent to the obligation of the Lenders to enter into the Credit Agreement and to make their respective extensions of credit to the Borrower under the Credit Agreement that EGL shall have executed and delivered this Agreement for the ratable benefit of the Lenders;"
  },
  {
    "id": "c004",
    "name": "1.01 Definitions—Incorporated terms",
    "text": "SECTION 1.01 Definitions. Capitalized terms used herein and not otherwise defined shall have the meanings assigned to such terms in the Credit Agreement."
  },
  {
    "id": "c005",
    "name": "1.01 “Agreement”",
    "text": "In this Agreement, unless the context requires otherwise, capitalized terms have the following respective meanings: “Agreement” means this Guarantee Agreement, as the same may be restated, amended, supplemented or otherwise modified from time to time."
  },
  {
    "id": "c006",
    "name": "1.01 “Borrower Obligations”",
    "text": "“Borrower Obligations” means the collective reference to the Obligations (as defined in the Credit Agreement), including the unpaid principal of and interest on the Term Loans, if EGL Guarantee Agreement any, or the LC Exposure and all other obligations and liabilities of the Borrower (including, without limitation, interest accruing at the then applicable rate provided in the Credit Agreement upon the occurrence of any Default or after the maturity of the Term Loans, if any, and interest accruing at the then applicable rate provided in the Credit Agreement after the filing of any petition in bankruptcy, or the commencement of any insolvency, reorganization or like proceeding, relating to the Borrower, whether or not a claim for post-filing or post-petition interest is allowed in such proceeding) to the Lenders, whether direct or indirect, absolute or contingent, due or to become due, or now existing or hereafter incurred, which may arise under, out of, or in connection with, the Credit Agreement, this Agreement, or the other Loan Documents, or any Letter of Credit, or any other document made, delivered or given in connection therewith, in each case whether on account of principal, interest, reimbursement obligations, fees, indemnities, costs, expenses or otherwise (including, without limitation, all fees and disbursements of counsel to the Facility Agent or the Lenders that are required to be paid by the Borrower pursuant to the terms of any of the foregoing agreements)."
  },
  {
    "id": "c007",
    "name": "1.01 “Deficiency”",
    "text": "“Deficiency” means, as determined by the Borrower or the Required Lenders, any actual shortfall, howsoever caused, in funds available to the Borrower required: (i) for any cost of the Project in excess of one billion ninety seven million Dollars (US$1,097,000,000) (unless such cost of the Project is increased in connection with a Permitted Project Change); or (ii) any increase in the cost of the Project in excess of that set forth in clause (i) due to any change in scope of the Project that is not a Permitted Project Change."
  },
  {
    "id": "c008",
    "name": "1.01 “EGL Guarantee Release Date”",
    "text": "“EGL Guarantee Release Date” means the date following the Commercial Operations Date when an offtake agreement or agreements, in each case, between the Borrower and Essar Steel Algoma Inc., Canada, or any other offtaker reasonably acceptable to the Lender or Lenders at such time whose Term Loan Exposures constitute not less than sixty six and two thirds percent (66 2/3%) of the total Term Loan Exposure, which provides for the arms’ length actual purchase, in the aggregate under all such agreements, of at least 2.76 million tons per annum of the iron ore pellets manufactured by the beneficiation and pellet plant of the Borrower which is included in the Project, each of which offtake agreements shall be in form and substance and for a term, in each case, reasonably acceptable to the Lender or Lenders whose Term Loan Exposure constitute not less than sixty six and two thirds percent (66 2/3%) of the total Term Loan Exposure, becomes effective,"
  },
  {
    "id": "c009",
    "name": "1.01 EGL Guarantee Release Date—Negotiation covenant",
    "text": "provided, however, the Lenders agree that on or before the satisfaction of the conditions set forth in Section 4.02 of the Credit Agreement, the Lenders shall negotiate in good faith with the Borrower with respect to the form and term of a draft pellet purchase agreement that would be reasonably acceptable to the Lenders with respect to an approved offtaker."
  },
  {
    "id": "c010",
    "name": "1.01 “Guarantor Obligations”",
    "text": "“Guarantor Obligations” shall have the meaning given such term in Section 2.01(a)."
  },
  {
    "id": "c011",
    "name": "1.01 “Material Adverse Effect”",
    "text": "“Material Adverse Effect” means a material adverse effect on (a) the business, financial condition, operations or performance or properties of the Guarantor since the date of this Agreement, (b) the ability of the Guarantor to perform its material obligations under this Agreement, or (c) the rights of or remedies available to the Lenders under this Agreement."
  },
  {
    "id": "c012",
    "name": "1.01 “Obligations”",
    "text": "“Obligations”: (i) in the case of the Borrower, the Borrower Obligations, and (ii) in the case of the Guarantor, its Guarantor Obligations."
  },
  {
    "id": "c013",
    "name": "1.02(a) Singular and plural",
    "text": "SECTION 1.02 Rules of Interpretation. In this Agreement (a) the singular includes the plural and the plural the singular;"
  },
  {
    "id": "c014",
    "name": "1.02(b) Gender",
    "text": "singular; (b) words importing any gender include the other"
  },
  {
    "id": "c015",
    "name": "1.02(c) Statutes and regulations",
    "text": "(c) references to statutes or regulations are to be construed as including all statutory or regulatory provisions consolidating, amending or replacing the statute or regulation referred to;"
  },
  {
    "id": "c016",
    "name": "1.02(d) Agreement references",
    "text": "(d) references to “herein”, “hereof”, “hereto”, “hereunder” and similar terms refer to the agreement or document in which they appear, as a whole, and not to any particular section, paragraph, or provision of such agreement or document;"
  },
  {
    "id": "c017",
    "name": "1.02(e) Including and enumerations",
    "text": "(e) references to “include”, “includes” and “including” are deemed to be followed by the phrase “without limitation”, and, the parties agree that a general statement which is followed by or referable to an enumeration of specific matters shall not be limited to matters similar to the matters specifically mentioned unless otherwise expressly indicated;"
  },
  {
    "id": "c018",
    "name": "1.02(f) Internal references",
    "text": "(f) references to the preamble, recitals, sections (or subsections), exhibits or schedules are to this Agreement unless otherwise indicated;"
  },
  {
    "id": "c019",
    "name": "1.02(g) Contractual instruments",
    "text": "(g) references to any agreements or other contractual instruments shall be deemed to include all schedules and exhibits to such agreements or contractual instruments and all amendments, modifications and supplements thereto, but only to the extent such amendments, modifications and supplements are not prohibited by either the terms thereof or hereof, unless otherwise expressly indicated;"
  },
  {
    "id": "c020",
    "name": "1.02(h) Persons",
    "text": "(h) references to Persons include their respective permitted successors and assigns, but only to the extent such succession or assignment is not prohibited by the terms hereof, and, in the case of Governmental Authorities, Persons succeeding to their respective functions and capacities"
  },
  {
    "id": "c021",
    "name": "1.02(i) Asset and property",
    "text": "(i) references to “asset” and “property” shall be construed to have the same meaning and effect and refer to any and all tangible and intangible assets and properties, including licenses, concessions, cash, securities, accounts and contractual and other rights (including rights to revenue)."
  },
  {
    "id": "c022",
    "name": "1.03 Inconsistency with Loan Documents",
    "text": "SECTION 1.03 Inconsistency with Loan Documents. In the event of any conflict or inconsistency between the terms and provisions of this Agreement and any other Loan Document, the terms and provisions of this Agreement shall govern and control for the purposes of and to the extent of the matters covered by this Agreement."
  },
  {
    "id": "c023",
    "name": "2.01(a) Guarantor Obligations",
    "text": "SECTION 2.01 Guarantor Obligations. (a) EGL hereby unconditionally and irrevocably, (i) for the period from the date hereof to and until satisfaction of all conditions set forth in Sections 4.01 through 4.02 (including, in each case Section 4.04) of the Credit Agreement, guarantees to the Lenders the prompt and complete payment by the Borrower when due (whether at the stated maturity, by acceleration or otherwise) of the Borrower Obligations, (ii) for the period from the date hereof to and until the Commercial Operations Date, agrees to provide to the Borrower for the ratable benefit of the Borrower and the Lenders, the full and complete amount of any Deficiency when the Deficiency arises and the Guarantor receives notice of such Deficiency as set forth in Section 2.02(a) below, and (iii) for the period from the Commercial Operations Date and thereafter to and until the EGL Guarantee Release Date, guarantees to the Lenders, the prompt and complete payment by the Borrower when due (whether at the stated maturity, by acceleration or otherwise) of the Borrower Obligations, provided, the maximum amount of EGL’s liability for the Borrower Obligation under this clause (iii) shall be limited in the aggregate to $250,000,000, (collectively, the foregoing obligations are herein referred to as the “Guarantor Obligations”)."
  },
  {
    "id": "c024",
    "name": "2.01(b)(i) Primary obligations",
    "text": "(b) Anything herein or in any other Loan Document to the contrary notwithstanding, (i) the obligations of the Guarantor hereunder are primary and notwithstanding the obligations of EGL Guarantee Agreement 3 any other Person providing any Guarantee, Collateral or other assurance in favor of the Lenders on behalf of the Borrower Obligations;"
  },
  {
    "id": "c025",
    "name": "2.01(b)(ii) Maximum lawful liability",
    "text": "(ii) the maximum liability of the Guarantor hereunder and under the other Loan Documents shall in no event exceed the amount which can be guaranteed by the Guarantor under applicable federal and state laws relating to fraudulent conveyances or transfers or the insolvency of debtors."
  },
  {
    "id": "c026",
    "name": "2.01(c) Obligations exceeding liability",
    "text": "(c) The Guarantor agrees that the Borrower Obligations may at any time and from time to time exceed the amount of the liability of the Guarantor hereunder without impairing the guarantee of the Guarantor contained in this Section 2.01 or affecting the rights and remedies of the Facility Agent or any Lender hereunder."
  },
  {
    "id": "c027",
    "name": "2.01(d) Duration of guarantee",
    "text": "(d) The guarantee contained in this Section 2.01 shall remain in full force and effect until the earlier of (i) the EGL Guarantee Release Date, and (ii) the date that all the Borrower Obligations and the obligations of the Guarantor under the guarantee contained in this Section 2.01 shall have been paid in full in cash, no Letter of Credit shall be outstanding and the Total Commitments shall be terminated, notwithstanding that from time to time during the term of the Credit Agreement the Borrower may be free from any Borrower Obligations."
  },
  {
    "id": "c028",
    "name": "2.02(a) Borrower Deficiency notice",
    "text": "SECTION 2.02 Deficiency Procedures. (a) The Borrower shall notify the Guarantor from time to time to the extent a Deficiency at any time exists and that the Guarantor provides to the Borrower the amount of the Deficiency specified in such Deficiency notice."
  },
  {
    "id": "c029",
    "name": "2.02(a) Facility Agent Deficiency notice",
    "text": "If no action is taken by the Borrower to notify the Guarantor of a Deficiency, and the Required Lenders at any time determine that a Deficiency exists, the Facility Agent on behalf of the Required Lenders may give a notice of the Deficiency in writing to the Guarantor (with a copy to the Borrower), that the Guarantor provide to the Borrower the amount of the Deficiency specified in such Deficiency notice, which shall include a certification from the Lender’s Engineering Consultant of the Deficiency amount."
  },
  {
    "id": "c030",
    "name": "2.02(b) No obligation to issue notice",
    "text": "(b) The parties hereto acknowledge that the Facility Agent and the Lenders shall have no obligation to issue a notice of Deficiency to demand the provision of funds to the Borrower to meet a Deficiency in accordance with this Article II"
  },
  {
    "id": "c031",
    "name": "2.02(b) No liability for demands",
    "text": "and that neither the Facility Agent nor Lender shall be liable to any party for not demanding any funds or for demanding insufficient funds under this Article II."
  },
  {
    "id": "c032",
    "name": "2.02(d) Form of Deficiency funding",
    "text": "(d) Any funds required to cover a Deficiency specified in a notice of Deficiency shall be provided by way of a contribution to the capital of the Borrower or, in accordance with the provisions and requirements of the Credit Agreement, an Unsecured Subordinated Promoter Loan."
  },
  {
    "id": "c033",
    "name": "2.02(d) Capital contribution actions",
    "text": "If the Guarantor decides to contribute additional capital to the Borrower, the Borrower shall take all appropriate action to increase its charter capital and offer to the Guarantor or their Affiliate(s) as may be specified by the Guarantor the right to make a capital contribution to the Borrower."
  },
  {
    "id": "c034",
    "name": "2.02(f) Use of capital contribution",
    "text": "(f) If the Guarantor decides to contribute capital to the Borrower, the Guarantor agrees to cause Borrower, and the Borrower hereby agrees, to issue and allocate the additional Equity Interests subscribed and to pay the cost or cost that has created the Deficiency."
  },
  {
    "id": "c035",
    "name": "2.02(f) Use of promoter loan proceeds",
    "text": "If the Guarantor makes an Unsecured Subordinated Promoter Loan, the Guarantor agrees to cause Borrower, and the Borrower hereby agrees, to use the proceeds of such loan to pay the cost or cost that has created the Deficiency."
  },
  {
    "id": "c036",
    "name": "2.03 Subrogation restriction",
    "text": "SECTION 2.03 Subrogation. Notwithstanding any payment made by the Guarantor hereunder or any set-off or application of funds of the Guarantor by the Facility Agent or any EGL Guarantee Agreement 4 Lender, the Guarantor shall not be entitled to be subrogated to any of the rights of the Facility Agent or any Lender against the Borrower or any other Guarantor or any collateral security or guarantee or right of offset held by the Facility Agent or any Lender for the payment of the Guarantor Obligations, nor shall the Guarantor seek or be entitled to seek any contribution or reimbursement from the Borrower or any other Guarantor in respect of payments made by the Guarantor hereunder, until all Guarantor Obligations are paid in full in cash, no Letter of Credit shall be outstanding and the Total Commitments are terminated."
  },
  {
    "id": "c037",
    "name": "2.03 Trust and turnover of subrogation proceeds",
    "text": "If any amount shall be paid to the Guarantor on account of such subrogation rights or as a contribution at any time when all of the Guarantor Obligations shall not have been paid in full in cash, such amount shall be held by the Guarantor in trust for the Facility Agent and the Lenders, segregated from other funds of the Guarantor, and shall, forthwith upon receipt by the Guarantor, be turned over to the Facility Agent in the exact form received by the Guarantor (duly indorsed by the Guarantor to the Facility Agent, if required), to be applied against the Guarantor Obligations, whether matured or unmatured, in such order as the Facility Agent may determine."
  },
  {
    "id": "c038",
    "name": "2.03 Permitted reimbursement",
    "text": "Notwithstanding the foregoing, nothing herein shall prevent the reimbursement of the Guarantor in respect of any payment made by the Guarantor hereunder if such payment is permitted under Section 6.07 of the Credit Agreement."
  },
  {
    "id": "c039",
    "name": "2.04 Continuing obligation after amendments",
    "text": "SECTION 2.04 Amendments, etc. with respect to the Borrower Obligations. The Guarantor shall remain obligated hereunder notwithstanding that, without any reservation of rights against the Guarantor and without notice to or further assent by the Guarantor, any demand for payment of any of the Guarantor Obligations made by the Facility Agent or on behalf of the Lenders may be rescinded by the Facility Agent or the Lenders and any of the Guarantor Obligations continued, and the Guarantor Obligations, or the liability of any other Person upon or for any part thereof, or any collateral security or guarantee therefor or right of offset with respect thereto, may, from time to time, in whole or in part, be renewed, extended, amended, modified, accelerated, compromised, waived, surrendered or released by the Facility Agent or the Lenders, and the Credit Agreement and the other Loan Documents and any other documents executed and delivered in connection therewith may be amended, modified, supplemented or terminated, in whole or in part, as the Facility Agent (or the Required Lenders or all Lenders, as the case may be) may (with the consent of such of the Borrower as shall be required thereunder) deem advisable from time to time, and any collateral security, guarantee or right of offset at any time held by the Facility Agent or any Lender for the payment of the Guarantor Obligations may (with the consent of such of the Borrower and the Guarantor as shall be required thereunder) be sold, exchanged, waived, surrendered or released."
  },
  {
    "id": "c040",
    "name": "2.04 No duty to protect collateral",
    "text": "Neither the Facility Agent nor any Lender shall, except to the extent set forth in, and for the benefit of the parties to, the agreements and instruments governing such Lien or guarantee have any obligation to protect, secure, perfect or insure any Lien at any time held by it as security for the Guarantor Obligations or for the guarantees contained in this Article II or any property subject thereto."
  },
  {
    "id": "c041",
    "name": "2.05 Waiver of notices",
    "text": "SECTION 2.05 Guarantee Absolute and Unconditional. The Guarantor waives any and all notice of the creation, renewal, extension or accrual of any of the Borrower Obligations, notice of or proof of reliance by the Facility Agent or the Lenders upon the guarantee contained in this Agreement or acceptance of the guarantee contained in this Agreement and notice of any law, regulation, decree or order of any jurisdiction or any event affecting any term of a Guaranteed Obligation;"
  },
  {
    "id": "c042",
    "name": "2.05 Reliance as to Borrower Obligations",
    "text": "the Borrower Obligations, and any of them, shall conclusively be deemed to have been created, contracted or incurred, or renewed, extended, amended or waived, in reliance upon the guarantee contained in this Agreement;"
  },
  {
    "id": "c043",
    "name": "2.05 Waiver of diligence and demand",
    "text": "The Guarantor waives diligence, presentment, protest, and demand for payment and notice of default or nonpayment to or upon the Borrower or the Guarantor with respect to the Guarantor Obligations."
  },
  {
    "id": "c044",
    "name": "2.05 Continuing absolute guarantee",
    "text": "The Guarantor understands and agrees that the guarantee of the Guarantor contained in this Agreement shall be construed as a continuing, absolute and unconditional guarantee of payment and not merely of collection without regard to (i) the validity or enforceability of the Credit Agreement or any other Loan Document, any of the Guarantor Obligations or any other collateral security therefor (including the perfection of such collateral) or guarantee or right of offset with respect thereto at any time or from time to time held by the Facility Agent or any Lender, (ii) any defense, set-off or counterclaim (other than a defense of payment or performance) which may at any time be available to or be asserted by the Borrower or any other Person against the Facility Agent or any Lender, or (iii) any other circumstance whatsoever (with or without notice to or knowledge of the Borrower or the Guarantor) which constitutes, or might be construed to constitute, an equitable or legal discharge of the Borrower for the Borrower Obligations, or of the Guarantor under the guarantee of the Guarantor contained in this Agreement, in bankruptcy or in any other instance."
  },
  {
    "id": "c045",
    "name": "2.05 No obligation to pursue others",
    "text": "When making any demand hereunder or otherwise pursuing its rights and remedies hereunder against the Guarantor, the Facility Agent may, but shall be under no obligation to, make a similar demand on or otherwise pursue such rights and remedies as it may have against the Borrower, any other Guarantor or any other Person or against any collateral security or guarantee for the Borrower Obligations or any right of offset with respect thereto,"
  },
  {
    "id": "c046",
    "name": "2.05 Effect of failure to pursue others",
    "text": "and any failure by the Facility Agent to make any such demand, to pursue such other rights or remedies or to collect any payments from the Borrower, any other Guarantor or any other Person or to realize upon any such collateral security or guarantee or to exercise any such right of offset, or any release of the Borrower, any other Guarantor or any other Person or any such collateral security, guarantee or right of offset, shall not relieve the Guarantor of any obligation or liability under this Agreement, and shall not impair or affect the rights and remedies, whether express, implied or available as a matter of law, of the Facility Agent or any Lender against the Guarantor."
  },
  {
    "id": "c047",
    "name": "2.05 Definition of demand",
    "text": "For the purposes hereof “demand” shall include the commencement and continuance of any legal proceedings."
  },
  {
    "id": "c048",
    "name": "2.06 Reinstatement",
    "text": "SECTION 2.06 Reinstatement. The guarantee contained in this Agreement shall continue to be effective, or be reinstated, as the case may be, if at any time payment, or any part thereof, of any of the Guarantor Obligations is rescinded or must otherwise be restored or returned by the Facility Agent or any Lender upon the insolvency, bankruptcy, dissolution, liquidation or reorganization of the Guarantor, or upon or as a result of the appointment of a receiver, intervenor or conservator of, or trustee or similar officer for, the Guarantor or any substantial part of its property, or otherwise, all as though such payments had not been made."
  },
  {
    "id": "c049",
    "name": "2.07 Payments",
    "text": "SECTION 2.07 Payments. The Guarantor hereby guarantees that payments by it hereunder will be paid to the Lenders without set-off or counterclaim in Dollars."
  },
  {
    "id": "c050",
    "name": "Article III(a) Organization, authority, qualification and compliance",
    "text": "ARTICLE III REPRESENTATIONS, WARRANTIES AND COVENANTS To induce the Lenders to enter into the Credit Agreement and to make their respective extensions of credit to the Borrower thereunder, the Guarantor hereby represents and warrants to the Lenders and the Facility Agent on the date hereof, on the Effective Date and on each other date on which representations and warranties are made or deemed made under the Credit Agreement, that: EGL Guarantee Agreement 6 (a) The Guarantor (i) is duly organized, validly existing and in good standing under the laws of the jurisdiction of its organization, (ii) has the corporate power and authority, and the legal right, to own and operate its property, to lease the property it operates as lessee and to conduct the business in which it is currently engaged, (iii) is duly qualified as a foreign corporation and in good standing under the laws of each jurisdiction where its ownership, lease or operation of property or the conduct of its business requires such qualification except to the extent the failure to be so qualified could not, in the aggregate, reasonably be expected to have a Material Adverse Effect and (iv) is in compliance in all material respects with all laws, regulations and orders of any Governmental Authority applicable to it or its properties and all indentures, agreements and other instruments binding upon it or its properties."
  },
  {
    "id": "c051",
    "name": "Article III(b) Power and authorization",
    "text": "(b) The Guarantor has the corporate power and authority, and the legal right, to make, deliver and perform this Agreement and has taken all necessary corporate action to authorize the execution, delivery and performance of this Agreement;"
  },
  {
    "id": "c052",
    "name": "Article III(b) No governmental consent required",
    "text": "no consent or authorization of, filing with, notice to or other act by or in respect of, any Governmental Authority or any other Person is required in connection with the execution, delivery, performance, validity or enforceability of this Agreement;"
  },
  {
    "id": "c053",
    "name": "Article III(b) Due execution and delivery",
    "text": "this Agreement has been, and each other Loan Document to which it is a party will be, duly executed and delivered on behalf of the Guarantor;"
  },
  {
    "id": "c054",
    "name": "Article III(b) Valid and binding obligation",
    "text": "this Agreement constitutes, and each other Loan Document to which it is a party when executed and delivered will constitute, a legal, valid and binding obligation of the Guarantor enforceable against the Guarantor in accordance with its terms, subject to the effects of bankruptcy, insolvency, fraudulent conveyance, reorganization, moratorium and other similar laws relating to or affecting creditors' rights generally, general equitable principles (whether considered in a proceeding in equity or at law) and an implied covenant of good faith and fair dealing;"
  },
  {
    "id": "c055",
    "name": "Article III(c) No violation, default or Lien",
    "text": "(c) The execution, delivery and performance of this Agreement (i) will not violate any applicable law or regulation or any order of any Governmental Authority, or violate or result in a default under any indenture, agreement or other instrument binding upon the Guarantor or its assets, except to the extent that any such violations or defaults would not, individually, or in the aggregate, reasonably be expected to result in a Material Adverse Effect, and (ii) will not result in the creation or imposition of any Lien on any asset of the Guarantor;"
  },
  {
    "id": "c056",
    "name": "Article III(c) No unpaid duties or levies",
    "text": "and there is no requirement on the Guarantor, the Lenders or any Agent to file or pay any stamp duty, registration charges or any other statutory duties and levies except for those already paid;"
  },
  {
    "id": "c057",
    "name": "Article III(d) No material litigation",
    "text": "(d) No litigation, investigation or proceeding of or before any arbitrator or Governmental Authority is pending or, to the knowledge of Guarantor, threatened by or against the Guarantor or against any of its or their respective properties or revenues with respect to this Agreement or any of the transactions contemplated hereby, which would, individually or in the aggregate, reasonably be expect to result in a Material Adverse Effect;"
  },
  {
    "id": "c058",
    "name": "Article III(e)(a) Fair value of assets",
    "text": "(e) On the Effective Date and after giving effect to the application of the proceeds of any Loans under the Credit Agreement and to all Guarantor Obligations, (a) the fair value of the consolidated assets of the Guarantor, at a fair valuation, will exceed its consolidated debts and liabilities, subordinated, contingent or otherwise;"
  },
  {
    "id": "c059",
    "name": "Article III(e)(b) Fair saleable value",
    "text": "(b) the present fair saleable value of the consolidated property of Guarantor will be greater than the amount that will be required to pay the probable liability of its debts and other liabilities, subordinated, contingent or otherwise, as such consolidated debts and other liabilities become absolute and matured;"
  },
  {
    "id": "c060",
    "name": "Article III(e)(c) Ability to pay debts",
    "text": "(c) Guarantor will be able to pay its debts and liabilities, subordinated, contingent or otherwise, as such debts and liabilities become absolute and matured;"
  },
  {
    "id": "c061",
    "name": "Article III(e)(d) Adequate capital",
    "text": "and (d) Guarantor will not have unreasonably small capital with which to conduct the business in which it is engaged as such business is now conducted and is proposed to be conducted following the Effective Date;"
  },
  {
    "id": "c062",
    "name": "Article III(f) Pari passu ranking",
    "text": "(f) The Guarantor Obligations shall at all time rank at least pari passu in right of payment in insolvency with all its other present and future senior Indebtedness of the Guarantor;"
  },
  {
    "id": "c063",
    "name": "Article III(g) Guarantor personnel and Lender directors",
    "text": "(g) No governor, director, managing member, manager, or employee of the Guarantor is a director of a Lender"
  },
  {
    "id": "c064",
    "name": "Article III(g) Lender directors’ interests",
    "text": "and no director of a Lender holds a substantial Equity Interest in the Guarantor."
  },
  {
    "id": "c065",
    "name": "Article III(g) Banking company relationships",
    "text": "Except to the extent disclosed in the Disclosed Matters, none of the or governors or managers of the Guarantor is a director of a banking company (as defined under the Banking Regulation Act, 1949 of India) or specified near relation (as specified by the Reserve Bank of India) of a director of a banking company or a near relative of any senior officer of the Lenders;"
  },
  {
    "id": "c066",
    "name": "Article III(h) No willful defaulter",
    "text": "(h) In addition to the requirements of Section 4.13, neither the Guarantor nor any of its governors or managers has been declared to be a willful defaulter under the Banking Regulation Act, 1949 of India."
  },
  {
    "id": "c067",
    "name": "Article III(h) Removal of willful defaulter",
    "text": "In the event of a Person being identified as a willful defaulter, the Guarantor shall take expeditious and effective steps for the removal of such person as a governor or manager and this obligation shall be a covenant of the Guarantor during the term of this Agreement."
  },
  {
    "id": "c068",
    "name": "Article III(h) OFAC sanctions",
    "text": "Neither the Guarantor nor any of its agents acting or benefitting in any capacity in connection with this Agreement is a Specially Designated National under the sanctions administered by the Office of Foreign Assets Control (OFAC) and has not used and shall not use any part of the Facility in any transaction with or for the purpose of financing the activities of any person currently subject to any U.S. sanctions administered by OFAC, including, without limitation, those implemented by regulations codified in Subtitle B, Chapter V of Title 31, U.S. Code of Federal Regulations."
  },
  {
    "id": "c069",
    "name": "Article III(h) No banking, financial services or real estate business",
    "text": "The Guarantor is not involved in the business of banking or financial services and/or real estate (as defined in Regulation 2(p) of Notification FEMA 120, dated July 7, 2004 issued by the Reserve Bank of India) nor does it have a place of business in India;"
  },
  {
    "id": "c070",
    "name": "Article III(i) No immunity entitlement",
    "text": "(i) The Guarantor is not entitled in any jurisdiction in which judicial proceedings may at any time be commenced with respect to this Agreement, to claim for itself or its property, assets or revenues any immunity (whether by reason of sovereignty or otherwise) from suit, jurisdiction of any court, attachment prior to judgment, setoff, execution of a judgment or from any other legal process or remedy,"
  },
  {
    "id": "c071",
    "name": "Article III(i) Waiver of immunity",
    "text": "and to the extent that there may be attributed to the Borrower such an immunity (whether or not claimed), and to the extent that the Guarantor may hereafter be entitled to claim such an immunity, the Guarantor hereby irrevocably agrees not to claim and hereby irrevocably waives such immunity;"
  },
  {
    "id": "c072",
    "name": "Article III(j) No Default",
    "text": "(j) No Default in respect of the Guarantor has occurred and is continuing;"
  },
  {
    "id": "c073",
    "name": "Article III(k) Confidential Information Material",
    "text": "(k) The information contained in the Confidential Information Material with respect to the Guarantor (other than forecasts, projections, forward-looking information, assumption, conclusions, estimates, and pro forma calculations contained therein) when taken as a whole is true in all material respects as of the date of the Confidential Information Material; provided, however, that with respect to any forecasts, projections, forward-looking information, assumption, conclusions, estimates and pro forma calculations contained therein, the Guarantor represents only that such information regarding the Guarantor was prepared in good faith based upon assumptions believed to be reasonable at the time, and no factual information was omitted from the Confidential Information Material so as to make the Confidential Information Material misleading in any material respect with respect to the Guarantor as of the date of the Confidential Information Material; and"
  },
  {
    "id": "c074",
    "name": "Article III(l) No more favorable support",
    "text": "(l) The Guarantor covenants and agrees with the Facility Agent and the Lenders that it shall not provide any guarantee or other support in favor of any Project Lender which is not a EGL Guarantee Agreement 8 Lender upon terms and conditions that are substantially more favorable to the beneficiary thereof than as are provided by the Guarantor in this Agreement."
  },
  {
    "id": "c075",
    "name": "Article III(m) Notice of Default and Material Adverse Effect",
    "text": "(m) Promptly (and not later than five (5) Business Days) after any Responsible Officer of the Guarantor obtains knowledge thereof, Guarantor will furnish to the Lenders or the Facility Agent, on behalf of each Lender written notice of the following: 1. the occurrence of any Default known to the Guarantor, including any material breach of any representation hereunder; 2. any development or event that has or results in, or would reasonably be expected to have or result in, a Material Adverse Effect on the Guarantor."
  },
  {
    "id": "c076",
    "name": "Article III(n) Asset disposition restriction",
    "text": "(n) The Guarantor shall not sell or otherwise dispose of, whether by a single transaction or a series of transactions (related or not), any or all of its assets or properties which would materially and adversely affect the ability of such Guarantor to perform its obligations under this Agreement or whose sale or disposition would result in an event which, with the passage of time or the giving of notice or both, would become an Event of Default, provided that the aforesaid restriction shall not apply to an arms length sale or disposal of its assets or properties."
  },
  {
    "id": "c077",
    "name": "Article III(o) Payments to Guarantors",
    "text": "(o) The Borrower shall make no payments to either Guarantor as a commission or in consideration for the delivery of either Guarantee Agreement on its behalf except from proceeds available from the Unrestricted Account;"
  },
  {
    "id": "c078",
    "name": "Article III(o) Permitted payments",
    "text": "provided, however, nothing herein shall prevent the Borrower from paying to the Parent dividends, redemptions of capital or to either Guarantor payments in connection with any Unsecured Subordinated Promoter Loans as permitted in accordance with the Credit Agreement."
  },
  {
    "id": "c079",
    "name": "4.01 No deemed waiver",
    "text": "SECTION 4.01 No Waiver by Course of Conduct; Cumulative Remedies. Neither the Facility Agent nor any Lender shall by any act (except by a written instrument pursuant to Section 4.12), delay, indulgence, omission or otherwise be deemed to have waived any right or remedy hereunder or to have acquiesced in any Default or Event of Default or any failure to perform any of the Guarantor Obligations."
  },
  {
    "id": "c080",
    "name": "4.01 No waiver by failure or delay",
    "text": "No failure to exercise, nor any delay in exercising, on the part of the Facility Agent or any Lender, any right, power or privilege hereunder shall operate as a waiver thereof."
  },
  {
    "id": "c081",
    "name": "4.01 No preclusion by partial exercise",
    "text": "No single or partial exercise of any right, power or privilege hereunder shall preclude any other or further exercise thereof or the exercise of any other right, power or privilege."
  },
  {
    "id": "c082",
    "name": "4.01 Occasion-specific waiver",
    "text": "A waiver by the Facility Agent or any Lender of any right or remedy hereunder on any one occasion shall not be construed as a bar to any right or remedy which the Facility Agent or such Lender would otherwise have on any future occasion."
  },
  {
    "id": "c083",
    "name": "4.01 Cumulative remedies",
    "text": "The rights and remedies herein provided are cumulative, may be exercised singly or concurrently and are not exclusive of any other rights or remedies provided by law."
  },
  {
    "id": "c084",
    "name": "4.02(a) Enforcement expenses",
    "text": "SECTION 4.02 Enforcement Expenses; Indemnification. (a) The Guarantor agrees to pay, or reimburse the Facility Agent for, its reasonable costs and expenses incurred in collecting against the Guarantor under the guarantee contained in this Agreement or otherwise enforcing or preserving any rights or obligations under this Agreement, including, without limitation, the reasonable fees and disbursements of counsel to the Facility Agent."
  },
  {
    "id": "c085",
    "name": "4.02(b) Taxes",
    "text": "(b) The Guarantor agrees to pay, and to save the Facility Agent and the Lenders harmless from, any and all liabilities with respect to, or resulting from any delay in paying, any and all stamp, excise, sales or other taxes which may be payable or determined to be payable with respect to this Agreement."
  },
  {
    "id": "c086",
    "name": "4.02(c) Survival",
    "text": "(c) The agreements in this Section shall survive repayment of the Obligations and all other amounts payable under the Credit Agreement."
  },
  {
    "id": "c087",
    "name": "4.03 Binding effect",
    "text": "SECTION 4.03 Successors and Assigns. This Agreement shall be binding upon the successors and assigns of the Guarantor and shall inure to the benefit of the Facility Agent and the Lenders and their successors and assigns;"
  },
  {
    "id": "c088",
    "name": "4.03 Assignment restriction",
    "text": "provided that the Guarantor may not assign, transfer or delegate any of its rights or obligations under this Agreement without the prior written consent of the Facility Agent."
  },
  {
    "id": "c089",
    "name": "4.04 Set-off right",
    "text": "SECTION 4.04 Set-Off. The Guarantor hereby irrevocably authorizes the Facility Agent and each Lender at any time and from time to time while an Event of Default shall have occurred and be continuing, without notice to the Guarantor or any other Guarantor, any such notice being expressly waived by the Guarantor, to set-off and appropriate and apply any and all deposits (general or special, time or demand, provisional or final), in any currency, and any other credits, indebtedness or claims, in any currency, in each case whether direct or indirect, absolute or contingent, matured or unmatured, at any time held or owing by the Facility Agent or such Lender to or for the credit or the account of the Guarantor, or any part thereof in such amounts as the Facility Agent or such Lender may elect, against and on account of the obligations and liabilities of the Guarantor to the Facility Agent or such Lender hereunder and claims of every nature and description of the Facility Agent or such Lender against the Guarantor, in any currency, whether arising hereunder, under the Credit Agreement, any other Loan Document or otherwise, as the Facility Agent or such Lender may elect, whether or not the Facility Agent or any Lender has made any demand for payment and although such obligations, liabilities and claims may be contingent or unmatured."
  },
  {
    "id": "c090",
    "name": "4.04 Notice of set-off",
    "text": "The Facility Agent and each Lender shall notify the Guarantor promptly of any such set-off and the application made by the Facility Agent or such Lender of the proceeds thereof, provided that the failure to give such notice shall not affect the validity of such set-off and application."
  },
  {
    "id": "c091",
    "name": "4.04 Additional remedies",
    "text": "The rights of the Facility Agent and each Lender under this Section are in addition to other rights and remedies (including, without limitation, other rights of set-off) which the Facility Agent or such Lender may have."
  },
  {
    "id": "c092",
    "name": "4.05 Execution in counterparts",
    "text": "SECTION 4.05 Counterparts. This Agreement may be executed by one or more of the parties to this Agreement on any number of separate counterparts (including by telecopy),"
  },
  {
    "id": "c093",
    "name": "4.05 Counterparts constitute one instrument",
    "text": "and all of said counterparts taken together shall be deemed to constitute one and the same instrument."
  },
  {
    "id": "c094",
    "name": "4.06 Severability in a jurisdiction",
    "text": "SECTION 4.06 Severability. Any provision of this Agreement which is prohibited or unenforceable in any jurisdiction shall, as to such jurisdiction, be ineffective to the extent of such prohibition or unenforceability without invalidating the remaining provisions hereof,"
  },
  {
    "id": "c095",
    "name": "4.06 Enforceability in other jurisdictions",
    "text": "and any such prohibition or unenforceability in any jurisdiction shall not invalidate or render unenforceable such provision in any other jurisdiction."
  },
  {
    "id": "c096",
    "name": "4.07 Section Headings",
    "text": "SECTION 4.07 Section Headings. The Section headings used in this Agreement are for convenience of reference only and are not to affect the construction hereof or be taken into consideration in the interpretation hereof."
  },
  {
    "id": "c097",
    "name": "4.08 Integration",
    "text": "SECTION 4.08 Integration. This Agreement and the other Loan Documents represent the agreement of the Guarantor, the Facility Agent and the Lenders with respect to the EGL Guarantee Agreement 10 subject matter hereof and thereof, and there are no promises, undertakings, representations or warranties by the Facility Agent or any Lender relative to subject matter hereof and thereof not expressly set forth or referred to herein or in the other Loan Documents."
  },
  {
    "id": "c098",
    "name": "4.09 Governing Law",
    "text": "SECTION 4.09 GOVERNING LAW. THIS AGREEMENT SHALL BE GOVERNED BY, AND CONSTRUED AND INTERPRETED IN ACCORDANCE WITH, THE LAW OF THE STATE OF NEW YORK."
  },
  {
    "id": "c099",
    "name": "4.10(a) Jurisdiction consent",
    "text": "SECTION 4.10 Submission to Jurisdiction; Venue; Process Agent. (a) The Guarantor hereto irrevocably hereby expressly waives all right to object to jurisdiction or execution in any legal action or proceeding relating to this Agreement which it may now or hereafter have by reason of its domicile or by reason of any subsequent or other domicile and hereby irrevocably consents that any legal action, suit or proceeding arising out of or relating to this Agreement or any of the Loan Documents and any other document or instrument required to be executed in relation thereto may be instituted in or (other than by the Guarantor) removed to the U.S. federal and New York state courts located in the Borough of Manhattan, City and State of New York, and by execution and delivery of this Agreement, each party hereto submits to and accepts and consents with regard to any such action or proceeding for itself and in respect of its properties and assets, generally and unconditionally, the jurisdiction of any such court."
  },
  {
    "id": "c100",
    "name": "4.10(a) Enforcement of judgment",
    "text": "The Guarantor agrees that a judgment in any such action, suit or proceeding may be enforced in any other jurisdiction, including Singapore, by suit upon such judgment, a certified copy of which shall be conclusive evidence of judgment."
  },
  {
    "id": "c101",
    "name": "4.10(a) Venue and inconvenient forum waiver",
    "text": "The Guarantor hereby waives any objection it may now or hereafter have to the laying of the venue of any such action, suit or proceeding, and further waives any claim that any such action, suit or proceeding brought in any of the aforesaid courts has been brought in any inconvenient forum."
  },
  {
    "id": "c102",
    "name": "4.10(b) Process agent designation",
    "text": "(b) The Guarantor shall irrevocably designate Essar Americas, Inc., with its office at 277 Park Avenue, 35th Floor, New York, New York 10017, U.S.A., and its successors as the Guarantor’s designee, appointee and agent to receive, accept and acknowledge, for and on behalf of the Guarantor, service of any and all legal process, summons, notices and documents which may be served in such action, suit or proceeding relating to the Credit Agreement, this Agreement or any other Loan Documents in the case of the courts located in the Borough of Manhattan, City and State of New York, which service may be made on any such designee, appointee and agent in accordance with legal procedures prescribed for such courts."
  },
  {
    "id": "c103",
    "name": "4.10(b) Maintenance and replacement of process agent",
    "text": "So long as the Guarantor has any obligations under this Agreement, the Guarantor agree to take any and all action necessary to continue such designation in full force and effect and should such designee, appointee and agent become unavailable for this purpose for any reason not attributable to the Guarantor, the Guarantor will immediately grant a similar special irrevocable power of attorney to a new designee, appointee and agent with offices in [New York], which shall irrevocably agree to act as such, with the powers and for purposes specified in this Section 4.10."
  },
  {
    "id": "c104",
    "name": "4.10(b) Consent to service",
    "text": "Each of the Guarantor further irrevocably consents and agrees to service of any and all legal process, summons, notices and documents out of any of the aforesaid courts in any such action, suit or proceeding relating to this Agreement or any other Loan Documents delivered to the Guarantor in accordance with this Section 4.10 or to its then designee, appointee or agent for service."
  },
  {
    "id": "c105",
    "name": "4.10(b) Copy of process",
    "text": "If service is made upon such designee, appointee and agent, a copy of such process, summons, notice or document shall also be provided to the Guarantor, by recognized international courier; provided, that failure to provide such copy to the Guarantor shall not impair or affect in any way the validity of such service or any judgment rendered in such action or proceedings."
  },
  {
    "id": "c106",
    "name": "4.10(b) Validity of service",
    "text": "Each of the Guarantor agrees that service upon the Guarantor or any such designee, appointee and agent as provided for herein EGL Guarantee Agreement 11 shall constitute valid and effective personal service upon the Guarantor with respect to matters contemplated in this Section 4.10 and that the failure of any such designee, appointee and agent to give any notice of such service to the Guarantor shall not impair or affect in any way the validity of such service or any judgment rendered in any action or proceeding based thereon."
  },
  {
    "id": "c107",
    "name": "4.10(b) Proceedings in other venues",
    "text": "Nothing herein shall limit or be construed to limit the rights of the Lenders to commence proceedings against the Guarantor in any other venue where assets of the Guarantor may be found."
  },
  {
    "id": "c108",
    "name": "4.11 Waiver of Jury Trial",
    "text": "SECTION 4.11 WAIVER OF JURY TRIAL. EACH OF THE PARTIES TO THIS AGREEMENT HEREBY KNOWINGLY, VOLUNTARILY AND INTENTIONALLY WAIVES ANY RIGHT IT MAY HAVE TO A TRIAL BY JURY OF ANY CLAIM, DEMAND OR CAUSE OF ACTION UNDER OR IN CONNECTION WITH THIS AGREEMENT."
  },
  {
    "id": "c109",
    "name": "4.12 Written form and delivery methods",
    "text": "SECTION 4.12 Notices. All notices, requests, consents, demands and other communications (collectively, “notices”) required or permitted to be given under this Agreement to any Person shall be in writing and shall be personally delivered, delivered by internationally recognized courier service or telefaxed (with a confirmation copy by internationally recognized courier service),"
  },
  {
    "id": "c110",
    "name": "4.12 Effectiveness of notices",
    "text": "and shall be effective when received,"
  },
  {
    "id": "c111",
    "name": "4.12 Notice addresses",
    "text": "and shall be directed to the address of the Guarantor set forth below its signature below, and as to the Borrower, any Lender or the Facility Agent, to such Person in the manner and address as required under the Credit Agreement."
  },
  {
    "id": "c112",
    "name": "4.13 Patriot Act notice",
    "text": "SECTION 4.13 Patriot Act. Each Lender and the Facility Agent, when appointed hereunder, (for itself and not on behalf of any Lender) hereby notifies the Guarantor that pursuant to the requirements of the Patriot Act, it is required to obtain, verify and record information that identifies the Guarantor, which information includes the name and address of the Guarantor and other information that will allow such Lender or the Facility Agent, as applicable, to identify the Guarantor in accordance with the Patriot Act."
  },
  {
    "id": "c113",
    "name": "4.13 Know-your-customer information",
    "text": "The Guarantor agrees to provide the Lenders, upon request, with all documentation and other information required from time to time to be obtained by the Lenders pursuant to applicable “know your customer” and anti-money laundering rules and regulations, including the Patriot Act."
  },
  {
    "id": "c114",
    "name": "4.14 Entire Agreement",
    "text": "SECTION 4.14 Entire Agreement. This Agreement constitutes the entire agreement of each party with respect to the subject matter hereof and supersedes all prior negotiations, agreements, discussions, correspondence, memoranda and understandings (whether written or oral) of each party concerning or relating to the subject matter of this Agreement."
  },
  {
    "id": "c115",
    "name": "4.15 Binding effect and benefit",
    "text": "SECTION 4.15 Benefit of Agreement. This Agreement shall be binding upon, and inure to the benefit of, the parties hereto and their successors and assigns;"
  },
  {
    "id": "c116",
    "name": "4.15 Assignment restriction",
    "text": "provided that the Guarantor shall not the right to assign or transfer its rights and obligations hereunder without the prior written consent of the Facility Agent and the Lenders."
  },
  {
    "id": "c117",
    "name": "4.15 No third-party rights",
    "text": "Nothing in this Agreement, whether expressed or implied, shall be construed to give any Person (other than the Lenders) not a party to this Agreement any legal or equitable right, remedy or claim under or in respect of this Agreement."
  }
]

