 {"clause_id": "c061", "issues": [
   {"issue": "\"[U]nreasonably small capital with which to conduct the business\" as it \"is proposed to be conducted\" has no measurable boundary and depends on unstated projections. The solvency representation turns on a phrase the clause never defines.", "type": 1, "prob": 0.12}
 ]},
 {"clause_id": "c062", "issues": [
   {"issue": "\"[S]hall at all time rank at least pari passu\" is a continuing covenant cast among representations, and \"senior Indebtedness of the Guarantor\" is not defined in this Agreement. Whether it warrants a present fact or promises future ranking is unclear.", "type": 1, "prob": 0.2}
 ]},
 {"clause_id": "c063", "issues": []},
 {"clause_id": "c064", "issues": [
   {"issue": "\"[S]ubstantial Equity Interest\" fixes no percentage or other threshold, so the representation has no ascertainable boundary. Nothing elsewhere in the Agreement supplies a measure.", "type": 1, "prob": 0.2}
 ]},
 {"clause_id": "c065", "issues": [
   {"issue": "The sentence is mechanically defective — \"none of the or governors or managers of the Guarantor\" omits a noun — so the class of persons covered is not stated. The scope of the Reserve Bank of India relationship representation turns on that missing word.", "type": 1, "prob": 0.18}
 ]},
 {"clause_id": "c066", "issues": [
   {"issue": "The opening cross-reference, \"[i]n addition to the requirements of Section 4.13,\" points to the Patriot Act provision, which imposes no willful-defaulter requirement under the Banking Regulation Act, 1949 of India. The cross-reference cannot be given effect as written.", "type": 2, "prob": 0.2}
 ]},
 {"clause_id": "c067", "issues": [
   {"issue": "\"[E]xpeditious and effective steps for the removal\" of a willful defaulter sets no time limit and no measure of effectiveness, and does not say who identifies the person. Whether the Guarantor has complied is not testable against the words.", "type": 1, "prob": 0.2}
